update.foreach:
UPDATE vm_horn_content_conf
SET file_url = #{item.fileUrl},
    file_duration = #{item.duration},
    file_md5 = #{item.md5}
WHERE resource_id = #{item.audioId}

UPDATE vm_horn_task_play_param
SET file_url = #{item.fileUrl},
    file_duration = #{item.duration},
    file_md5 = #{item.md5}
WHERE file_id = #{item.txtId}
